import {LANES,SIGNATURES} from './data.js';
export function download(name,data,type='application/octet-stream'){const blob=data instanceof Blob?data:new Blob([data],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),10000);}
const vlq=n=>{let a=[n&127];while(n>>=7)a.unshift((n&127)|128);return a;};
const be=(n,bytes)=>Array.from({length:bytes},(_,i)=>(n>>((bytes-i-1)*8))&255);
export function exportMidi(events,bpm,signature='4/4',totalSteps=16){let track=[0,255,81,3,...be(Math.round(6e7/bpm),3),0,255,88,4,+signature.split('/')[0],Math.log2(+signature.split('/')[1]),24,8];let notes=[];for(const e of events){const lane=LANES.find(l=>l.id===e.lane);if(lane){const tick=Math.max(0,Math.min(totalSteps*120-1,Math.round((e.step+(e.offset||0))*120)));notes.push({tick,data:[153,lane.note,e.velocity]},{tick:Math.min(totalSteps*120,tick+60),data:[137,lane.note,0]});}}notes.sort((a,b)=>a.tick-b.tick);let last=0;for(const n of notes){track.push(...vlq(n.tick-last),...n.data);last=n.tick;}track.push(...vlq(Math.max(0,totalSteps*120-last)),255,47,0);return new Uint8Array([...Array.from('MThd',c=>c.charCodeAt(0)),0,0,0,6,0,0,0,1,1,224,...Array.from('MTrk',c=>c.charCodeAt(0)),...be(track.length,4),...track]);}
export function importMidi(buffer,map){const a=new Uint8Array(buffer),dv=new DataView(buffer);let p=0;const str=n=>{const s=String.fromCharCode(...a.slice(p,p+n));p+=n;return s};const u32=()=>{const v=dv.getUint32(p);p+=4;return v};const variable=()=>{let n=0,b,count=0;do{if(p>=a.length||count++>4)throw Error('Invalid MIDI variable length');b=a[p++];n=(n<<7)|(b&127)}while(b&128);return n;};if(str(4)!=='MThd')throw Error('Choose a standard MIDI (.mid) file.');const len=u32();if(len<6)throw Error('Invalid MIDI header');const format=dv.getUint16(p),tracks=dv.getUint16(p+2),ppq=dv.getUint16(p+4);if(format>1||ppq&32768||!ppq)throw Error('Only MIDI format 0/1 with musical ticks is supported.');p+=len;let events=[],bpm=112,signature='4/4',max=0,declaredEnd=0,unmapped=0;for(let tr=0;tr<tracks;tr++){if(str(4)!=='MTrk')throw Error('Missing MIDI track');let end=p+4+u32(),tick=0,status=0;while(p<end){tick+=variable();let b=a[p++];if(b<128){p--;b=status}else if(b<240)status=b;if(b===255){const type=a[p++],n=variable();if(type===81&&n===3)bpm=Math.round(6e7/((a[p]<<16)|(a[p+1]<<8)|a[p+2]));if(type===47)declaredEnd=Math.max(declaredEnd,tick);if(type===88)signature=`${a[p]}/${2**a[p+1]}`;p+=n;continue;}if(b===240||b===247){const length=variable();p+=length;continue;}const command=b&240;const d1=a[p++],d2=(command===192||command===208)?0:a[p++];if(command===144&&d2>0){const lane=map[d1];if(lane){events.push({lane,step:Math.floor(tick/ppq*4+1e-8),velocity:d2,prob:1,offset:tick/ppq*4-Math.floor(tick/ppq*4+1e-8)});max=Math.max(max,tick/ppq*4);}else unmapped++;}}p=end;}if(!SIGNATURES[signature])throw Error(`Time signature ${signature} is not supported yet.`);if(max>=SIGNATURES[signature]*64||declaredEnd/ppq*4>SIGNATURES[signature]*64+.000001)throw Error('Import a MIDI clip of 64 bars or fewer.');return {events,bpm,signature,bars:Math.max(1,Math.ceil(Math.max(max+.000001,declaredEnd/ppq*4-.000001)/SIGNATURES[signature])),unmapped};}
export function wav(buffer){const channels=buffer.numberOfChannels,length=buffer.length*channels*2,out=new ArrayBuffer(44+length),v=new DataView(out);const s=(o,t)=>[...t].forEach((c,i)=>v.setUint8(o+i,c.charCodeAt(0)));s(0,'RIFF');v.setUint32(4,36+length,true);s(8,'WAVE');s(12,'fmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,channels,true);v.setUint32(24,buffer.sampleRate,true);v.setUint32(28,buffer.sampleRate*channels*2,true);v.setUint16(32,channels*2,true);v.setUint16(34,16,true);s(36,'data');v.setUint32(40,length,true);let p=44;for(let i=0;i<buffer.length;i++)for(let c=0;c<channels;c++){const x=Math.max(-1,Math.min(1,buffer.getChannelData(c)[i]));v.setInt16(p,x<0?x*32768:x*32767,true);p+=2;}return out;}
// Store-only ZIP: no external libraries or network dependency.
export function zip(files){const enc=new TextEncoder(),chunks=[],central=[];let offset=0;const table=Array.from({length:256},(_,n)=>{for(let i=0;i<8;i++)n=(n&1)?0xedb88320^(n>>>1):n>>>1;return n>>>0});const crc=a=>{let n=0xffffffff;for(const b of a)n=table[(n^b)&255]^(n>>>8);return (n^0xffffffff)>>>0};const h=(size)=>{const a=new Uint8Array(size);return [a,new DataView(a.buffer)]};for(const [name,data]of files){const bytes=data instanceof Uint8Array?data:new Uint8Array(data),nb=enc.encode(name),[a,v]=h(30),sum=crc(bytes);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint32(14,sum,true);v.setUint32(18,bytes.length,true);v.setUint32(22,bytes.length,true);v.setUint16(26,nb.length,true);chunks.push(a,nb,bytes);const [c,w]=h(46);w.setUint32(0,0x02014b50,true);w.setUint16(4,20,true);w.setUint16(6,20,true);w.setUint32(16,sum,true);w.setUint32(20,bytes.length,true);w.setUint32(24,bytes.length,true);w.setUint16(28,nb.length,true);w.setUint32(42,offset,true);central.push(c,nb);offset+=a.length+nb.length+bytes.length;}const [end,e]=h(22);e.setUint32(0,0x06054b50,true);e.setUint16(8,files.length,true);e.setUint16(10,files.length,true);e.setUint32(12,central.reduce((n,a)=>n+a.length,0),true);e.setUint32(16,offset,true);return new Blob([...chunks,...central,end],{type:'application/zip'});}
